/bin/bash -lc "cd [workspace path] && python3 - <<'EOF'
try:
    import cv2; print('cv2', cv2.__version__)
except ImportError: print('no cv2')
import scipy; print('scipy', scipy.__version__)
import numpy as np
from PIL import Image
im = np.array(Image.open('first_frame.png')).astype(int)
# Pillow top profile: for each x, find first y (from 80 down) where pixel is pillow-ish (brighter/warmer)
# Wall ~ (146,140,140); pillow similar but with darker seam. Use luminance difference vs local wall.
for x in [10,30,50,70,90,110,130,150,170,190,204,220,240,250]:
    col = im[80:144, x]
    lum = col.mean(axis=1)
    # find first big change
    print(x, lum[:12].astype(int))
EOF"
